//! minimp3 (CC0) and PDMP3 (Unlicense), which agree on every Huffman code
//! and band edge; do not edit by hand.

/// One Huffman code: `len` bits, value `code` (MSB first), decoding to
/// the pair (x, y) for big-value tables or the flags v w x y (bits 3..0)
/// for the count1 tables.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Code {
    pub len: u8,
    pub code: u16,
    pub x: u8,
    pub y: u8,
}

const fn c(len: u8, code: u16, x: u8, y: u8) -> Code {
    Code { len, code, x, y }
}

